#!/usr/bin/env bash
# Generates Copilot CLI and Codex agent files from the Claude Code agent types in agents/, so
# every harness runs the same roles from one source.
#   Copilot: <role>.agent.md, the same body, a Copilot model ID, and the effort as a first line
#            (a Copilot agent file cannot pin effort; pass it per launch).
#   Codex:   <role>.toml, the body as developer_instructions and the effort as
#            model_reasoning_effort; no model, so Codex uses the session's.
#   sync-agents.sh          regenerate
#   sync-agents.sh --check  exit 1 when a generated file is missing, stale or orphaned
# Outputs default to ~/.copilot/agents and ~/.codex/agents when that harness is installed;
# AGENTS_COPILOT and AGENTS_CODEX override them (empty skips one), AGENTS_SRC the source.
# Only files this script generated are ever replaced or removed.
# COPILOT_MODEL_<FAMILY> overrides a mapping (e.g. COPILOT_MODEL_OPUS=claude-opus-5.5).
set -euo pipefail
src="${AGENTS_SRC:-$(cd "$(dirname "$0")/.." && pwd)/agents}"
default() { [ -d "$HOME/$1" ] && echo "$HOME/$1/agents" || true; }
copilot="${AGENTS_COPILOT-$(default .copilot)}"
codex="${AGENTS_CODEX-$(default .codex)}"
mark='by agent-campaign sync-agents.sh'
check=; [ "${1:-}" = --check ] && check=1

model_for() {
	case $1 in
	opus) echo "${COPILOT_MODEL_OPUS:-claude-opus-5.5}" ;;
	sonnet) echo "${COPILOT_MODEL_SONNET:-claude-sonnet-5.5}" ;;
	haiku) echo "${COPILOT_MODEL_HAIKU:-claude-haiku-5.5}" ;;
	*) echo "$1" ;;
	esac
}
field() { sed -n "s/^$1: //p" "$2" | head -1; }
body() { awk 'BEGIN { n = 0 } /^---$/ && n < 2 { n++; next } n >= 2' "$1"; }

render_copilot() {
	printf -- '---\nname: %s\ndescription: %s\nmodel: %s\n---\n\n' "$(field name "$1")" "$(field description "$1")" "$(model_for "$(field model "$1")")"
	printf '<!-- Generated from agents/%s %s; edit the source. -->\n' "$(basename "$1")" "$mark"
	printf 'Launch effort: `%s` (pass it as `reasoning_effort`; a Copilot agent file cannot pin it).\n' "$(field effort "$1")"
	body "$1"
}

render_codex() {
	local effort
	effort=$(field effort "$1")
	printf '# Generated from agents/%s %s; edit the source.\n' "$(basename "$1")" "$mark"
	printf 'name = "%s"\ndescription = """%s"""\nmodel_reasoning_effort = "%s"\n' "$(field name "$1")" "$(field description "$1")" "$effort"
	printf 'developer_instructions = """\n%s\n"""\n' "$(body "$1" | sed 's/^\n//')"
}

stale=0
ours() { grep -qE "$mark|by campaign/scripts/sync-agents.sh" "$1" 2> /dev/null; }  # this one's marks
emit() {  # renderer, output file, source
	if [ -n "$check" ]; then
		cmp -s <("$1" "$3") "$2" || { echo "stale: $2"; stale=1; }
	elif [ -e "$2" ] && ! ours "$2"; then
		echo "skipped $2: not generated by this script" >&2
	else
		"$1" "$3" > "$2.tmp" && mv "$2.tmp" "$2"
	fi
}
outputs=0
for pair in "render_copilot:$copilot:agent.md" "render_codex:$codex:toml"; do
	render=${pair%%:*} rest=${pair#*:}; dir=${rest%:*} ext=${rest##*:}
	[ -n "$dir" ] || continue
	mkdir -p "$dir"
	for f in "$src"/*.md; do
		emit "$render" "$dir/$(basename "${f%.md}").$ext" "$f"
		outputs=$((outputs + 1))
	done
	for out in "$dir"/*."$ext"; do
		[ -e "$out" ] && ours "$out" || continue
		role=$(basename "${out%."$ext"}")
		[ -f "$src/$role.md" ] && continue
		if [ -n "$check" ]; then echo "orphan: $out"; stale=1; else rm -f "$out"; fi
	done
done
[ -n "$check" ] && exit $stale
echo "generated $outputs agent files from $(find "$src" -name '*.md' | wc -l | tr -d ' ') sources"
